query:
-- Fix Iowa Senate notes with correct percentages
UPDATE senate_races SET notes = 'Josh Turek won D primary with 62.7% (120,213 votes) vs Zach Wahls 37.3% (71,621 votes). Ashley Hinson won R primary with 74.2% (152,956 votes) vs Jim Carlin 25.8% (53,163 votes). Source: AP via NPR, June 3, 2026.' WHERE state_code = 'IA';

-- Fix NJ Senate notes with Murphy primary percentages
UPDATE senate_races SET notes = 'Cory Booker (D) ran uncontested. Justin Murphy won R primary with 33.3% (80,133 votes) vs Richard Tabor 29.2% (70,332), Alex Zdan 26.9% (64,620), Robert Lebovics 10.6% (25,595). Source: AP via NPR, June 3, 2026.' WHERE state_code = 'NJ';

-- Fix SD Senate notes with Rounds primary percentages
UPDATE senate_races SET notes = 'Mike Rounds won R primary with 75.8% (101,471 votes) vs Justin McNeal 24.2% (32,412 votes). Julian Beaudion (D) ran uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'SD';

-- Fix SD Governor: Dan Ahlers won D primary uncontested
UPDATE governor_races SET dem_candidate = 'Dan Ahlers', notes = 'Historic first-ever SD gubernatorial runoff. R primary: Toby Doeden 30.6% (41,791) vs Larry Rhoden 25.2% (34,379) vs Dusty Johnson 23.4% (31,925) vs Jon Hansen 20.8% (28,390). Neither R candidate hit 35% threshold. R runoff July 28, 2026. Dan Ahlers (D) ran uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'SD';

-- Fix Iowa Governor notes with Lahn margin
UPDATE governor_races SET notes = 'Kim Reynolds not seeking re-election. Zach Lahn won R primary by razor-thin margin: 38.0% (80,338) vs Randy Feenstra 37.2% (78,713) — margin of 1,625 votes. Feenstra conceded. Rob Sand (D) ran uncontested. Cook Political Report: Toss-up. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'IA';

-- Fix NM Governor notes
UPDATE governor_races SET notes = 'Michelle Luján Grisham is term-limited. Open seat. Deb Haaland (D, former Interior Secretary) and Gregg Hull (R) both won their primaries June 2, 2026. Cook Political Report: Likely D. Source: AP, June 3, 2026.' WHERE state_code = 'NM';

-- Fix CA-48 notes (remove stale Campa-Najjar reference)
UPDATE house_races SET notes = 'Open seat (Darrell Issa retiring). Top-two primary June 2, 2026. Marni von Wilpert (D) and Jim Desmond (R) advanced. Ammar Campa-Najjar (D) finished 3rd and conceded. Source: AP/KPBS, June 3, 2026.' WHERE state_code = 'CA' AND district = 48;

-- Fix IA-4 notes (add Feenstra context)
UPDATE house_races SET notes = 'Open seat: Randy Feenstra (R) vacated to run for Governor (lost R primary to Zach Lahn). Dave Dawson won D primary 39.1% (11,285 votes) vs Stephanie Steiner 30.6% vs Ashley WolfTornabane 30.4%. Chris McGowan (R) ran uncontested. Source: AP via NPR, June 3, 2026.' WHERE state_code = 'IA' AND district = 4;

